import{_ as l,a0 as p,w as o,s as r,I as t,x as e,a1 as i,A as n,ao as d}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const L=JSON.parse('{"title":"使用 Ledger 记录（财务）情况 | LCTT x X-CMD","titleTemplate":false,"description":"使用 Ledger 记录（财务）情况 | LCTT (201807) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"使用 Ledger 记录（财务）情况 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"使用 Ledger 记录（财务）情况 | LCTT (201807) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201807/20141127 Keeping (financial) score with Ledger ","title":"使用 Ledger 记录（财务）情况","tag":"201807","desc":""},"relativePath":"201807/20141127 Keeping (financial) score with Ledger .md","filePath":"[post].md"}'),g={name:"201807/20141127 Keeping (financial) score with Ledger .md"};function h(u,s,k,f,b,m){const a=p("Link");return o(),r("div",null,[s[18]||(s[18]=t("h1",{id:"使用-ledger-记录-财务-情况",tabindex:"-1"},[e("使用 Ledger 记录（财务）情况 "),t("a",{class:"header-anchor",href:"#使用-ledger-记录-财务-情况","aria-label":"Permalink to “使用 Ledger 记录（财务）情况”"},"​")],-1)),t("p",null,[s[1]||(s[1]=e("自 2005 年搬到加拿大以来，我使用 ",-1)),i(a,{href:"http://www.ledger-cli.org/"},{default:n(()=>[...s[0]||(s[0]=[e("Ledger CLI",-1)])]),_:1}),s[2]||(s[2]=e(" 来跟踪我的财务状况。我喜欢纯文本的方式，它支持虚拟信封意味着我可以同时将我的银行帐户余额和我的虚拟分配到不同的目录下。以下是我们如何使用这些虚拟信封分别管理我们的财务状况。",-1))]),s[19]||(s[19]=d(`<p>每个月，我都有一个条目将我生活开支分配到不同的目录中，包括家庭开支的分配。W- 不要求太多， 所以我要谨慎地处理这两者之间的差别和我自己的生活费用。我们处理它的方式是我支付固定金额，这是贷记我支付的杂货。由于我们的杂货总额通常低于我预算的家庭开支，因此任何差异都会留在标签上。我过去常常给他写支票，但最近我只是支付偶尔额外的大笔费用。</p><p>这是个示例信封分配：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>2014.10.01 * Budget</span></span>
<span class="line"><span> [Envelopes:Living]</span></span>
<span class="line"><span> [Envelopes:Household] $500</span></span>
<span class="line"><span> ;; More lines go here</span></span></code></pre></div><p>这是设置的信封规则之一。它鼓励我正确地分类支出。所有支出都从我的 “Play” 信封中取出。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>= /^Expenses/</span></span>
<span class="line"><span> (Envelopes:Play) -1.0</span></span></code></pre></div><p>这个为家庭支出报销 “Play” 信封，将金额从 “Household” 信封转移到 “Play” 信封。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>= /^Expenses:House$/</span></span>
<span class="line"><span> (Envelopes:Play) 1.0</span></span>
<span class="line"><span> (Envelopes:Household) -1.0</span></span></code></pre></div><p>我有一套定期的支出来模拟我的预算中的家庭开支。例如，这是 10 月份的。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>2014.10.1 * House</span></span>
<span class="line"><span> Expenses:House</span></span>
<span class="line"><span> Assets:Household $-500</span></span></code></pre></div><p>这是杂货交易的形式：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>2014.09.28 * No Frills</span></span>
<span class="line"><span> Assets:Household:Groceries $70.45</span></span>
<span class="line"><span> Liabilities:MBNA:September $-70.45</span></span></code></pre></div><p>接着 <code>ledger bal Assets:Household</code> 就会告诉我是否欠他钱（负余额）。如果我支付大笔费用（例如：机票、通管道），那么正常家庭开支预算会逐渐减少余额。</p><p>我从 W- 那找到了一个为我的信用卡交易添加一个月标签的技巧，他还使用 Ledger 跟踪他的交易。它允许我再次检查条目的余额，看看前一个条目是否已被正确清除。</p><p>这个资产分类使用有点奇怪，但它在精神上对我有用。</p><p>使用 Ledger 以这种方式跟踪它可以让我跟踪我们的杂货费用以及我实际支付费用和我预算费用之间的差额。如果我最终支出超出预期，我可以从更多可自由支配的信封中移动虚拟货币，因此我的预算始终保持平衡。</p><p>Ledger 是一个强大的工具。相当极客，但也许更多的工作流描述可能会帮助那些正在搞清楚它的人！</p><hr>`,17)),t("p",null,[s[4]||(s[4]=e("via: ",-1)),i(a,{href:"http://sachachua.com/blog/2014/11/keeping-financial-score-ledger/"},{default:n(()=>[...s[3]||(s[3]=[e("http://sachachua.com/blog/2014/11/keeping-financial-score-ledger/",-1)])]),_:1})]),t("p",null,[s[9]||(s[9]=e("作者：",-1)),i(a,{href:"http://sachachua.com"},{default:n(()=>[...s[5]||(s[5]=[e("Sacha Chua",-1)])]),_:1}),s[10]||(s[10]=e(" 选题：",-1)),i(a,{href:"https://github.com/lujun9972"},{default:n(()=>[...s[6]||(s[6]=[e("lujun9972",-1)])]),_:1}),s[11]||(s[11]=e(" 译者：",-1)),i(a,{href:"https://github.com/geekpi"},{default:n(()=>[...s[7]||(s[7]=[e("geekpi",-1)])]),_:1}),s[12]||(s[12]=e(" 校对：",-1)),i(a,{href:"https://github.com/wxy"},{default:n(()=>[...s[8]||(s[8]=[e("wxy",-1)])]),_:1})]),t("p",null,[s[15]||(s[15]=e("本文由 ",-1)),i(a,{href:"https://github.com/LCTT/TranslateProject"},{default:n(()=>[...s[13]||(s[13]=[e("LCTT",-1)])]),_:1}),s[16]||(s[16]=e(" 原创编译，",-1)),i(a,{href:"https://linux.cn/"},{default:n(()=>[...s[14]||(s[14]=[e("Linux中国",-1)])]),_:1}),s[17]||(s[17]=e(" 荣誉推出",-1))])])}const T=l(g,[["render",h]]);export{L as __pageData,T as default};
